from taf.alias.store import store


class managedobject(store):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    _namespace = "managedobject"

    """ Create a library instance for managed object related keywords."""

    def setup(self, alias, group=None):
        """
        Setup the current managed object.

        :param str alias: alias name for the setup
        :param str group: (optional) group name of the setup, defaults to value None
        """
        managed_object = self.get_alias_value(alias)
        managed_object.setup(group=group)

    def teardown(self, alias, group=None, force=False):
        """
        Teardown the current managed object.

        By default a managed object, which still has dependers, that are up,
        cannot be torn down. First the dependers need to be torn down. This
        behaviour can be changed using force flag.

        :param str alias: alias name for the teardown
        :param str group: (optional) group name of the setup, defaults to value None
        :param bool force: (optional) if True, execute teardown irrespective of dependers state
        """
        managed_object = self.get_alias_value(alias)
        managed_object.teardown(group=group, force=force)

    def add_prerequisite(self, name, prerequisite):
        """
        Adding depender in given managed object

        Establish a prerequisite-relation between the ManagedObject referenced by "name" and
        the ManagedObject referenced by "prerequisite". During setup, "prerequisite" will be
        set up before "name". During teardown, "name" will be torn down before "prerequisite".

        :param str name: managed object alias name
        :param str prerequisite: dependency object alias name
        """
        managed_object = self.get_alias_value(name)
        depender = self.get_alias_value(prerequisite)
        managed_object.add_prerequisite(depender)
